replace_fn('normalizeProjectState',"""function normalizeProjectState(v){let x=v&&typeof v==='object'?v:{},projects=Array.isArray(x.projects)?x.projects:[];projects=projects.map(p=>({id:String(p?.id||uid()),name:String(p?.name||'Project').trim()||'Project',sessions:[...new Set((Array.isArray(p?.sessions)?p.sessions:[]).map(String).filter(Boolean))],activeSession:String(p?.activeSession||'')}));if(!projects.length)projects=[{id:'general',name:'General',sessions:[],activeSession:''}];let active=(x.activeProjectId==='__unassigned__'||projects.some(p=>p.id===x.activeProjectId))?x.activeProjectId:projects[0].id,normMap=o=>{let r={};if(o&&typeof o==='object')for(let[k,val]of Object.entries(o))if(k)r[String(k)]={...(val&&typeof val==='object'?val:{})};return r};return{schema:3,activeProjectId:active,unassignedActive:String(x.unassignedActive||''),projects,known:normMap(x.known),missing:normMap(x.missing),recovered:normMap(x.recovered),tabStyles:normMap(x.tabStyles)}}""")
