replace_fn('renderProjectTabs',"""function renderProjectTabs(){let root=$('projectTabs');if(!root)return;if(state.settings.clientType!=='botschat'){root.innerHTML='';return}let p=activeProject(),ss=p.sessions.map(k=>state.sessions.find(s=>s.key===k)).filter(Boolean);root.innerHTML=ss.map(x=>{let v=sessionState(x.key,x),rec=recoveredMeta(x.key);return`<button class="projectTab ${state.current?.key===x.key?'active':''}" draggable="true" data-project-session="${esc(x.key)}"${tabStyleAttr(x.key)}><span class="sessionState ${statusClass(v)}" title="${statusText(v)}"></span><span class="tabLabel">${esc(name(x))}${rec?' · recovered':''}</span><span class="tabClose" data-project-close="${esc(x.key)}" title="Soft delete → Recycle Bin">×</span></button>`}).join('')+`<button class="projectTabAdd" id="projectTabAdd" title="Add or create session">+</button>`;root.querySelectorAll('[data-project-session]').forEach(b=>{b.onclick=e=>{if(e.target.closest('[data-project-close]'))return;let k=b.dataset.projectSession;setActiveViewSession(k);select(k)};b.oncontextmenu=e=>{e.preventDefault();e.stopPropagation();openTabContext(b.dataset.projectSession,e.clientX,e.clientY)};b.ondragstart=e=>{closeTabContext();b.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/session-key',b.dataset.projectSession)};b.ondragend=()=>{b.classList.remove('dragging');root.querySelectorAll('.dragBefore,.dragAfter').forEach(x=>x.classList.remove('dragBefore','dragAfter'))};b.ondragover=e=>{let k=e.dataTransfer.getData('text/session-key');if(!k||k===b.dataset.projectSession)return;e.preventDefault();let z=b.getBoundingClientRect(),after=e.clientX>z.left+z.width/2;b.classList.toggle('dragBefore',!after);b.classList.toggle('dragAfter',after)};b.ondragleave=()=>b.classList.remove('dragBefore','dragAfter');b.ondrop=e=>{let k=e.dataTransfer.getData('text/session-key');if(!k||k===b.dataset.projectSession)return;e.preventDefault();let z=b.getBoundingClientRect(),after=e.clientX>z.left+z.width/2;b.classList.remove('dragBefore','dragAfter');if(assignedProjectFor(k)?.id===p.id)reorderProjectTab(k,b.dataset.projectSession,after)}});root.querySelectorAll('[data-project-close]').forEach(b=>b.onclick=e=>{e.stopPropagation();softDeleteSession(b.dataset.projectClose)});$('projectTabAdd').onclick=openProjectSessionPicker}""")
